START TRANSACTION;
CREATE TABLE pet_skill_sale_policy(policy_key VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,unit_price DECIMAL(30,3) NOT NULL,PRIMARY KEY(policy_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO pet_skill_sale_policy VALUES('default',1000000000);
CREATE TABLE pet_skill_sale_operations(operation_id BIGINT UNSIGNED NOT NULL,player_id BIGINT UNSIGNED NOT NULL,player_pet_id BIGINT UNSIGNED NOT NULL,sale_mode ENUM('single','all') NOT NULL,total_quantity BIGINT UNSIGNED NOT NULL,unit_price DECIMAL(30,3) NOT NULL,total_gain DECIMAL(30,3) NOT NULL,point_before DECIMAL(30,3) NOT NULL,point_after DECIMAL(30,3) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),PRIMARY KEY(operation_id),CONSTRAINT fk_pet_skill_sale_op FOREIGN KEY(operation_id) REFERENCES operations(id) ON DELETE RESTRICT,CONSTRAINT fk_pet_skill_sale_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE RESTRICT,CONSTRAINT fk_pet_skill_sale_pet FOREIGN KEY(player_pet_id) REFERENCES player_pets(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE pet_skill_sale_lines(operation_id BIGINT UNSIGNED NOT NULL,sequence_no INT UNSIGNED NOT NULL,skill_id BIGINT UNSIGNED NOT NULL,quantity BIGINT UNSIGNED NOT NULL,inventory_before BIGINT UNSIGNED NOT NULL,inventory_after BIGINT UNSIGNED NOT NULL,PRIMARY KEY(operation_id,sequence_no),CONSTRAINT fk_pet_skill_sale_line_op FOREIGN KEY(operation_id) REFERENCES pet_skill_sale_operations(operation_id) ON DELETE RESTRICT,CONSTRAINT fk_pet_skill_sale_line_skill FOREIGN KEY(skill_id) REFERENCES skill_definitions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO command_registry(command_code,handler_key,auth_scope,rollout_state,enabled,version) VALUES('PET_SKILL_SELL_ALL','pet_skill_sale_lifecycle','VERIFIED_USER','SHADOW',TRUE,1),('PET_SKILL_SELL','pet_skill_sale_lifecycle','VERIFIED_USER','SHADOW',TRUE,1) ON DUPLICATE KEY UPDATE handler_key=VALUES(handler_key),auth_scope=VALUES(auth_scope),rollout_state=VALUES(rollout_state),enabled=TRUE,version=version+1;
INSERT INTO command_aliases(command_text,command_code,active) VALUES('/펫스킬전체판매','PET_SKILL_SELL_ALL',TRUE),('/펫스킬판매','PET_SKILL_SELL',TRUE) ON DUPLICATE KEY UPDATE command_code=VALUES(command_code),active=TRUE;
COMMIT;
